// WF-TRY-WEBCALL · caps and limits. Runs before any proof is checked and before
// anything reaches Retell. State lives in workflow static data, which n8n saves
// after each production execution: a courtesy under concurrent runs, not a lock.
const NOW = Date.now();
const HOUR = 3600000;
const NONCE_TTL = 180000;
const DAILY_CAP = 40;
const IP_ATTEMPTS = 3;
// A CHALLENGE IS NOT AN ATTEMPT. From v4 the page pre-solves the puzzle on load
// and refreshes it every 150s so the tap is instant, which is 24 challenges in an
// hour on one open tab before a visitor has called anything. Issuing a nonce
// costs this workflow one cheap execution and costs Retell nothing; what stands
// in front of a CALL is IP_ATTEMPTS, the daily cap and the 10-slot reserve, and
// none of those move. 90 leaves room for a few tabs and still bounds the abuse.
const IP_CHALLENGES = 90;
const MAX_NONCES = 500;
const BITS = 20;

const req = $input.first().json;
const headers = req.headers || {};
const body = req.body && typeof req.body === 'object' ? req.body : {};
const step = String(body.step || '');

// IP SOURCE: set from the headers this instance actually receives (see the run
// report). Cloudflare sets cf-connecting-ip itself and a client cannot forge it;
// a client CAN prepend its own entries to x-forwarded-for.
function clientIp(h) {
  const cf = String(h['cf-connecting-ip'] || '').trim();
  if (cf) return cf;
  const xff = String(h['x-forwarded-for'] || '').split(',').map((s) => s.trim()).filter(Boolean);
  return xff.length ? xff[0] : 'unknown';
}
const ip = clientIp(headers);

const S = $getWorkflowStaticData('global');
if (!S.nonces || typeof S.nonces !== 'object') S.nonces = {};
if (!S.ipLog || typeof S.ipLog !== 'object') S.ipLog = {};
if (!S.chLog || typeof S.chLog !== 'object') S.chLog = {};
if (!S.day || typeof S.day !== 'object') S.day = { d: '', n: 0 };
for (const k of Object.keys(S.nonces)) if (NOW - S.nonces[k] > NONCE_TTL) delete S.nonces[k];
for (const log of [S.ipLog, S.chLog]) {
  for (const k of Object.keys(log)) {
    const kept = (Array.isArray(log[k]) ? log[k] : []).filter((t) => NOW - t < HOUR);
    if (kept.length) log[k] = kept; else delete log[k];
  }
}

const out = (json) => [{ json }];
const refuse = (status, error) => out({ next: false, status, body: { error } });

if (step === 'challenge') {
  const seen = S.chLog[ip] || [];
  if (seen.length >= IP_CHALLENGES) return refuse(429, 'rate_limited');
  if (Object.keys(S.nonces).length >= MAX_NONCES) return refuse(429, 'busy');
  seen.push(NOW);
  S.chLog[ip] = seen;
  let nonce = '';
  while (nonce.length < 32) nonce += Math.floor(Math.random() * 4294967296).toString(16).padStart(8, '0');
  nonce = nonce.slice(0, 32);
  S.nonces[nonce] = NOW;
  return out({ next: false, status: 200, body: { nonce, bits: BITS } });
}

if (step === 'call') {
  const today = new Date(NOW).toISOString().slice(0, 10);
  if (S.day.d !== today) S.day = { d: today, n: 0 };
  if (S.day.n >= DAILY_CAP) return refuse(429, 'busy');
  const tries = S.ipLog[ip] || [];
  if (tries.length >= IP_ATTEMPTS) return refuse(429, 'rate_limited');
  tries.push(NOW);
  S.ipLog[ip] = tries;
  return out({ next: true, nonce: String(body.nonce || ''), counter: String(body.counter || '') });
}

return refuse(400, 'bad_request');

// WF-TRY-WEBCALL · proof of work. The page spent about a million SHA-256 hashes
// finding a counter; checking it here takes one. Every nonce is single use and
// expires after three minutes, pass or fail.
// SHA-256 in plain JavaScript: the n8n Code sandbox is not guaranteed to allow
// require('crypto'). ASCII input only; the callers validate that first.
function sha256Words(str) {
  const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];
  const bytes = [];
  for (let i = 0; i < str.length; i++) bytes.push(str.charCodeAt(i) & 0xff);
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  bytes.push(0, 0, 0, 0, (bitLen >>> 24) & 0xff, (bitLen >>> 16) & 0xff, (bitLen >>> 8) & 0xff, bitLen & 0xff);
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const W = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      W[t] = (bytes[off + 4 * t] << 24) | (bytes[off + 4 * t + 1] << 16) | (bytes[off + 4 * t + 2] << 8) | bytes[off + 4 * t + 3];
    }
    for (let t = 16; t < 64; t++) {
      const x = W[t - 15], y = W[t - 2];
      const s0 = ((x >>> 7) | (x << 25)) ^ ((x >>> 18) | (x << 14)) ^ (x >>> 3);
      const s1 = ((y >>> 17) | (y << 15)) ^ ((y >>> 19) | (y << 13)) ^ (y >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) | 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let t = 0; t < 64; t++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) | 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map((w) => w >>> 0);
}
function leadingZeroBits(str) {
  let n = 0;
  for (const w of sha256Words(str)) {
    if (w === 0) { n += 32; continue; }
    n += Math.clz32(w);
    break;
  }
  return n;
}

const NONCE_TTL = 180000;
const BITS = 20;

const x = $input.first().json;
const nonce = String(x.nonce || '');
const counter = String(x.counter || '');
const S = $getWorkflowStaticData('global');
const nonces = S.nonces && typeof S.nonces === 'object' ? S.nonces : {};
const issued = nonces[nonce];
if (issued !== undefined) delete nonces[nonce];

const refuse = () => [{ json: { next: false, status: 403, body: { error: 'verification' } } }];
if (!/^[0-9a-f]{32}$/.test(nonce) || !/^[0-9]{1,15}$/.test(counter)) return refuse();
if (issued === undefined || Date.now() - issued > NONCE_TTL) return refuse();
if (leadingZeroBits(nonce + ':' + counter) < BITS) return refuse();
return [{ json: { next: true } }];

// WF-TRY-WEBCALL · capacity. The account runs 20 calls at once and web calls
// share them with both phone lines. At 10 busy the demo steps aside.
const BUSY_AT = 10;
const r = $input.first().json;
const busy = r && r.body && r.body.current_concurrency;
if (!r || r.statusCode !== 200 || typeof busy !== 'number') {
  return [{ json: { next: false, status: 502, body: { error: 'call_failed' } } }];
}
if (busy >= BUSY_AT) return [{ json: { next: false, status: 429, body: { error: 'busy' } } }];
return [{ json: { next: true } }];

// WF-TRY-WEBCALL · the only fields the browser gets back, and the daily count.
// Retell's error detail stays in this execution's log; the browser gets a code.
const r = $input.first().json;
const b = r && r.body;
const ok = r && r.statusCode >= 200 && r.statusCode < 300 && b && b.call_id && b.access_token;
if (!ok) return [{ json: { status: 502, body: { error: 'call_failed' } } }];
const S = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (!S.day || typeof S.day !== 'object' || S.day.d !== today) S.day = { d: today, n: 0 };
S.day.n = (S.day.n || 0) + 1;
return [{ json: { status: 200, body: {
  call_id: b.call_id, access_token: b.access_token, transport: b.transport, ice_servers: b.ice_servers, url: b.url,
} } }];

// WF-TRY-WEBCALL · another website asked. This stops browsers on other sites,
// not a script that sets its own Origin header; the limits behind it do that.
return [{ json: { status: 403, body: { error: 'forbidden' } } }];

// WF-TRY-WEBCALL · receipt limits. Every refusal here happens before anything
// reaches Retell, so a flood costs this workflow an execution and costs the
// Retell account nothing. State lives in workflow static data, same as the
// create-call side: a budget under concurrent runs, not a lock.
const NOW = Date.now();
const HOUR = 3600000;
const WINDOW = 7200000;   // a receipt is answered for two hours after the call started
const IP_POLLS = 60;      // per rolling hour — one call polls at most 15 times
const CALL_POLLS = 15;    // per call_id, ever: 45s of polling at 5s is 9
const MAX_CALLS = 500;

const req = $input.first().json;
const headers = req.headers || {};
const query = req.query && typeof req.query === 'object' ? req.query : {};
const callId = String(query.call_id || '');

// Same IP source as the create-call side: Cloudflare sets cf-connecting-ip and a
// client cannot forge it; a client CAN prepend its own x-forwarded-for entries.
function clientIp(h) {
  const cf = String(h['cf-connecting-ip'] || '').trim();
  if (cf) return cf;
  const xff = String(h['x-forwarded-for'] || '').split(',').map((s) => s.trim()).filter(Boolean);
  return xff.length ? xff[0] : 'unknown';
}
const ip = clientIp(headers);

const out = (json) => [{ json }];
const refuse = (status, error) => out({ next: false, status, body: { error } });

// A string that is not shaped like a call id never costs a request. 404 and not
// 400, so probing the endpoint tells an outsider nothing it did not already know.
if (!/^call_[0-9a-f]{16,64}$/.test(callId)) return refuse(404, 'not_found');

const S = $getWorkflowStaticData('global');
if (!S.rcIp || typeof S.rcIp !== 'object') S.rcIp = {};
if (!S.rcCall || typeof S.rcCall !== 'object') S.rcCall = {};
for (const k of Object.keys(S.rcIp)) {
  const kept = (Array.isArray(S.rcIp[k]) ? S.rcIp[k] : []).filter((t) => NOW - t < HOUR);
  if (kept.length) S.rcIp[k] = kept; else delete S.rcIp[k];
}
for (const k of Object.keys(S.rcCall)) {
  const e = S.rcCall[k];
  if (!e || typeof e !== 'object' || NOW - (e.t || 0) > WINDOW) delete S.rcCall[k];
}

// The ceiling is checked only for a call_id this workflow has not seen, so a
// visitor already polling is never evicted by a crowd arriving behind them.
const known = Object.prototype.hasOwnProperty.call(S.rcCall, callId);
if (!known && Object.keys(S.rcCall).length >= MAX_CALLS) return refuse(429, 'busy');

const seen = S.rcIp[ip] || [];
if (seen.length >= IP_POLLS) return refuse(429, 'rate_limited');
const entry = known ? S.rcCall[callId] : { n: 0, t: NOW };
if (entry.n >= CALL_POLLS) return refuse(429, 'rate_limited');

seen.push(NOW);
S.rcIp[ip] = seen;
entry.n += 1;
S.rcCall[callId] = entry;

return out({ next: true, call_id: callId });

// WF-TRY-WEBCALL · the trip sheet the browser is allowed to see.
//
// Retell's call record carries the caller's name, mobile, email and the full
// transcript. None of that crosses this node. What leaves is the trip: where,
// when, how many, which car, what it was quoted at — plus the recording of the
// visitor's own call and a yes/no on whether a mobile was captured at all.
//
// THE TRANSCRIPT COMES BACK REDACTED, and the reason it comes back at all is a
// measured one. retell-client-js-sdk@3.0.1 does emit an `update` event carrying
// the running transcript — but these calls are allocated Retell's GATEWAY
// transport, whose "control" data channel delivered no transcript events at all
// on a real call (5 turns server-side, 0 on the page). So the page cannot draw
// the thread live and fills it from here once the call ends.
//
// A transcript is prose, and prose is where a spoken name, number or email
// lives. Three passes strip them: the exact values the analyser already
// extracted, then any email, then any run of digits long enough to be a phone
// number. Over-redaction is the safe direction and is chosen deliberately.
const WINDOW = 7200000;
const NOW = Date.now();
const r = $input.first().json;
const notFound = [{ json: { status: 404, body: { error: 'not_found' } } }];

if (!r || r.statusCode !== 200 || !r.body || typeof r.body !== 'object') return notFound;
const call = r.body;

// Only calls this page created, and only for two hours after they started. Any
// other call id on the account answers exactly like one that does not exist.
if (!call.metadata || call.metadata.source !== 'aichauffeur.ai/try') return notFound;
const started = Number(call.start_timestamp || 0);
if (!started || NOW - started > WINDOW) return notFound;

const a = call.call_analysis || null;
const d = (a && a.custom_analysis_data) || {};
const str = (v) => { const s = String(v == null ? '' : v).trim(); return s ? s.slice(0, 80) : null; };
const num = (v) => (typeof v === 'number' && isFinite(v) && v > 0 ? String(v) : null);

// caller_mobile is read as a yes/no and then dropped. The digits never leave.
const mobile = String(d.caller_mobile == null ? '' : d.caller_mobile).replace(/\D/g, '');

// The exact strings the analyser pulled out of this call, longest first so that
// a full name is removed before either of its halves can be matched separately.
const known = [d.caller_name, d.caller_mobile, d.caller_email]
  .map((v) => String(v == null ? '' : v).trim())
  .filter((v) => v.length >= 3)
  .sort((x, y) => y.length - x.length);

function scrub(line) {
  let out = String(line == null ? '' : line);
  for (const k of known) out = out.split(k).join('[removed]');
  out = out.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[removed]');
  out = out.replace(/(?:\+?\d[\s().-]*){7,}\d/g, '[removed]');
  return out.trim();
}

const turns = Array.isArray(call.transcript_object) ? call.transcript_object : [];
const thread = turns
  .filter((t) => t && typeof t.content === 'string' && t.content.trim())
  .map((t) => ({ role: t.role === 'user' ? 'user' : 'agent', content: scrub(t.content).slice(0, 400) }))
  .filter((t) => t.content)
  .slice(0, 120);

return [{ json: { status: 200, body: {
  status: a ? 'ready' : 'processing',
  pickup: str(d.origin_city),
  dropoff: str(d.dropoff_address),
  date: str(d.pickup_date),
  time: str(d.pickup_time),
  passengers: num(d.passenger_count),
  vehicle: str(d.vehicle_class),
  quote: str(d.quote_total),
  ticket: str(call.metadata.ticket),
  mobile_captured: mobile.length >= 10,
  recording_url: typeof call.recording_url === 'string' && /^https:\/\//.test(call.recording_url) ? call.recording_url : null,
  transcript: thread.length ? thread : null,
} } }];

// WF-TRY-WEBCALL · another website asked for a receipt. Same answer the
// create-call side gives: this stops browsers on other sites, and the budget
// behind it is what stops a script.
return [{ json: { status: 403, body: { error: 'forbidden' } } }];
